const s=require('../../../../miniprogram/utils/service'),d=require('../../../../miniprogram/utils/domain');Page({data:{busy:false,error:'',r:null,photo:'',result:'够吃',note:'',feedback:[],units:['克','千克','个','毫升','升']},onLoad(o){this.id=o.id;this.load();},async load(){await s.run(this,async()=>{const c=await s.call();if(c.role!=='cook')throw Error('只有大厨可以编辑菜谱');const r=c.state.recipes.find(x=>x.id===this.id)||{id:'recipe-'+Date.now(),name:'',category:'家常',base:2,image:'',imageSource:'none',ingredients:[]};this.setData({r:d.clone(r),photo:s.display(r),feedback:c.state.feedback.filter(x=>x.recipeId===r.id).slice(-10).reverse()});});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},field(e){this.setData({r:{...this.data.r,[e.currentTarget.dataset.key]:e.detail.value}});},ingredient(e){const ingredients=this.data.r.ingredients.map((x,i)=>i===Number(e.currentTarget.dataset.index)?{...x,[e.currentTarget.dataset.key]:e.detail.value}:x);this.setData({r:{...this.data.r,ingredients}});},unit(e){const i=Number(e.currentTarget.dataset.index);this.setData({r:{...this.data.r,ingredients:this.data.r.ingredients.map((x,k)=>k===i?{...x,unit:this.data.units[Number(e.detail.value)]}:x)}});},add(){this.setData({r:{...this.data.r,ingredients:[...this.data.r.ingredients,{name:'',qty:'',unit:'克'}]}});},remove(e){const i=Number(e.currentTarget.dataset.index);wx.showModal({title:'移除这项食材？',content:'保存菜谱后才会生效，历史菜单不会被修改。',success:r=>{if(r.confirm)this.setData({r:{...this.data.r,ingredients:this.data.r.ingredients.filter((x,k)=>k!==i)}});}});},async photo(){await s.run(this,async()=>{const image=await s.upload();this.setData({r:{...this.data.r,image,imageSource:'user'},photo:image});});},async save(){let ok=false;await s.run(this,async()=>{await s.call('saveRecipe',{recipe:this.data.r});ok=true;wx.showToast({title:'菜谱已保存',icon:'success'});});if(ok)wx.navigateBack();},result(e){this.setData({result:e.currentTarget.dataset.value});},note(e){this.setData({note:e.detail.value});},async feedback(){await s.run(this,async()=>{await s.call('feedback',{recipeId:this.data.r.id,result:this.data.result,note:this.data.note});this.setData({note:''});wx.showToast({title:'经验已记下',icon:'success'});});},back(){wx.navigateBack();}});